#!/usr/bin/env bash
# Social-DL All-in-One App
# Version: 2.7.0
# Auto-generated - Edit source files instead!
# Repository: https://github.com/socialawkward/social-dl

set -o errexit
set -o nounset
set -o pipefail

# Farben
GREEN='\033[0;32m'
BLUE='\033[0;34m'
NC='\033[0m'

# Temporäres Arbeitsverzeichnis
TEMP_DIR=$(mktemp -d /tmp/social-dl-app-XXXXXX)
trap 'rm -rf "$TEMP_DIR"' EXIT

echo -e "${BLUE}📦 Social-DL App v2.7.0${NC}"
echo "Extracting files..."


# === social-dl.sh ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_social_dl_sh' | base64 -d > "$TEMP_DIR/social-dl.sh"

EOF_social_dl_sh
chmod +x "$TEMP_DIR/social-dl.sh"

# === install.sh ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_install_sh' | base64 -d > "$TEMP_DIR/install.sh"

EOF_install_sh
chmod +x "$TEMP_DIR/install.sh"

# === install-gui.sh ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_install_gui_sh' | base64 -d > "$TEMP_DIR/install-gui.sh"

EOF_install_gui_sh
chmod +x "$TEMP_DIR/install-gui.sh"

# === uninstall-gui.sh ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_uninstall_gui_sh' | base64 -d > "$TEMP_DIR/uninstall-gui.sh"

EOF_uninstall_gui_sh
chmod +x "$TEMP_DIR/uninstall-gui.sh"

# === README.md ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_README_md' | base64 -d > "$TEMP_DIR/README.md"

EOF_README_md

# === README.de.md ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_README_de_md' | base64 -d > "$TEMP_DIR/README.de.md"

EOF_README_de_md

# === CHANGELOG.md ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_CHANGELOG_md' | base64 -d > "$TEMP_DIR/CHANGELOG.md"

EOF_CHANGELOG_md

# === DEVELOPMENT-NOTES.md ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_DEVELOPMENT_NOTES_md' | base64 -d > "$TEMP_DIR/DEVELOPMENT-NOTES.md"

EOF_DEVELOPMENT_NOTES_md

# === config.example ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_config_example' | base64 -d > "$TEMP_DIR/config.example"

EOF_config_example

# === ui/mobile-app-ui-yad-tabs.sh ===
mkdir -p "$TEMP_DIR/ui"
cat << 'EOF_ui_mobile_app_ui_yad_tabs_sh' | base64 -d > "$TEMP_DIR/ui/mobile-app-ui-yad-tabs.sh"

EOF_ui_mobile_app_ui_yad_tabs_sh
chmod +x "$TEMP_DIR/ui/mobile-app-ui-yad-tabs.sh"

# === ui/mobile-app-ui-zenity.sh ===
mkdir -p "$TEMP_DIR/ui"
cat << 'EOF_ui_mobile_app_ui_zenity_sh' | base64 -d > "$TEMP_DIR/ui/mobile-app-ui-zenity.sh"

EOF_ui_mobile_app_ui_zenity_sh
chmod +x "$TEMP_DIR/ui/mobile-app-ui-zenity.sh"

# === ui/test-mobile-ui.sh ===
mkdir -p "$TEMP_DIR/ui"
cat << 'EOF_ui_test_mobile_ui_sh' | base64 -d > "$TEMP_DIR/ui/test-mobile-ui.sh"

EOF_ui_test_mobile_ui_sh
chmod +x "$TEMP_DIR/ui/test-mobile-ui.sh"

# === LICENSE ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_LICENSE' | base64 -d > "$TEMP_DIR/LICENSE"

EOF_LICENSE

# === social-dl-installer.desktop ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_social_dl_installer_desktop' | base64 -d > "$TEMP_DIR/social-dl-installer.desktop"

EOF_social_dl_installer_desktop

# === social-dl-uninstaller.desktop ===
mkdir -p "$TEMP_DIR/."
cat << 'EOF_social_dl_uninstaller_desktop' | base64 -d > "$TEMP_DIR/social-dl-uninstaller.desktop"

EOF_social_dl_uninstaller_desktop

# === GUI MENU ===

if ! command -v yad >/dev/null 2>&1 && ! command -v zenity >/dev/null 2>&1; then
    echo "Error: Neither YAD nor Zenity installed"
    echo "Install YAD (recommended): sudo pacman -S yad"
    echo "OR Zenity (fallback): sudo pacman -S zenity"
    exit 1
fi

cd "$TEMP_DIR"

# Standard-Sprache: Deutsch
LANG_MODE="de"

# === UI MODULE SELECTION ===
# Auto-detect YAD vs Zenity and embed appropriate UI module

if command -v yad >/dev/null 2>&1; then
    # YAD available - use enhanced UI with separate windows
    UI_TOOL="yad"
    
    # Source the YAD UI module
    source "$TEMP_DIR/ui/mobile-app-ui-yad-tabs.sh"
else
    # YAD not available - use Zenity fallback
    UI_TOOL="zenity"
    
    # Source the Zenity UI module
    source "$TEMP_DIR/ui/mobile-app-ui-zenity.sh"
fi

# === FUTURE FEATURE: BATCH DROP ZONE (Hidden Placeholder) ===
# This is a placeholder for future batch download functionality
# Will allow drag & drop of .txt or .md files containing URLs
# Implementation: Add zenity --file-selection with --multiple flag
# Parse each line of file as URL and pass to social-dl.sh
# Status: Not yet implemented - placeholder for v2.6+
# ============================================================

# Get script version
VERSION="2.7.0"

while true; do
    CHOICE=$(show_menu "$LANG_MODE" "$VERSION")
    
    # Exit wenn Cancel gedrückt
    [ $? -ne 0 ] && exit 0
    
    case "$CHOICE" in
        "1")  # Installieren
            if bash "./install-gui.sh"; then
                if [ "$LANG_MODE" = "de" ]; then
                    yad --info --image="dialog-information" --text="<span size='large'>✅</span>\n\n<b>Installation erfolgreich!</b>\n\nSocial-DL wurde installiert." --width=320 --title="Erfolg" --button="OK:0" 2>/dev/null || true
                else
                    yad --info --image="dialog-information" --text="<span size='large'>✅</span>\n\n<b>Installation successful!</b>\n\nSocial-DL has been installed." --width=320 --title="Success" --button="OK:0" 2>/dev/null || true
                fi
            else
                if [ "$LANG_MODE" = "de" ]; then
                    yad --error --image="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Installation fehlgeschlagen!</b>\n\nBitte Fehlermeldung prüfen." --width=320 --title="Fehler" --button="OK:0" 2>/dev/null || true
                else
                    yad --error --image="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Installation failed!</b>\n\nPlease check error messages." --width=320 --title="Error" --button="OK:0" 2>/dev/null || true
                fi
            fi
            ;;
        "2")  # Deinstallieren
            if bash "./uninstall-gui.sh"; then
                if [ "$LANG_MODE" = "de" ]; then
                    yad --info --image="dialog-information" --text="<span size='large'>✅</span>\n\n<b>Deinstallation erfolgreich!</b>\n\nSocial-DL wurde entfernt." --width=320 --title="Erfolg" --button="OK:0" 2>/dev/null || true
                else
                    yad --info --image="dialog-information" --text="<span size='large'>✅</span>\n\n<b>Uninstallation successful!</b>\n\nSocial-DL has been removed." --width=320 --title="Success" --button="OK:0" 2>/dev/null || true
                fi
            else
                if [ "$LANG_MODE" = "de" ]; then
                    yad --error --image="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Deinstallation fehlgeschlagen!</b>\n\nBitte Fehlermeldung prüfen." --width=320 --title="Fehler" --button="OK:0" 2>/dev/null || true
                else
                    yad --error --image="dialog-error" --text="<span size='large'>❌</span>\n\n<b>Uninstallation failed!</b>\n\nPlease check error messages." --width=320 --title="Error" --button="OK:0" 2>/dev/null || true
                fi
            fi
            ;;
        "3")  # README DE
            yad --text-info --filename="./README.de.md" \
                --width=900 --height=700 \
                --title="📖 README (Deutsch)" \
                --button="Schließen:0" \
                --fontname="Monospace 10" 2>/dev/null || true
            ;;
        "4")  # README EN
            yad --text-info --filename="./README.md" \
                --width=900 --height=700 \
                --title="📘 README (English)" \
                --button="Close:0" \
                --fontname="Monospace 10" 2>/dev/null || true
            ;;
        "5")  # Changelog
            yad --text-info --filename="./CHANGELOG.md" \
                --width=900 --height=700 \
                --title="📋 Changelog" \
                --button="Schließen/Close:0" \
                --fontname="Monospace 10" 2>/dev/null || true
            ;;
        "6")  # Info
            if [ "$LANG_MODE" = "de" ]; then
                yad --info --width=400 --height=420 --image="help-about" --title="ℹ️  Über Social-DL" \
                    --text="<span size='x-large'><b>Social-DL</b></span>
<span size='small'>Version 2.7.0</span>

<b>Universal Video &amp; Audio Downloader</b>
für Social Media Plattformen

<b>📱 Unterstützte Plattformen:</b>
• Instagram
• Twitter / X
• YouTube
• Reddit
• TikTok

<b>💻 Entwickelt mit ❤️ von:</b>
• Grok (Basis &amp; Features)
• Claude (Security &amp; Production)
• Perplexity (Edge-Cases &amp; Optimierungen)

<b>🔗 Repository:</b>
<span foreground='#0969DA'>github.com/socialawkward/social-dl</span>

<b>📄 Lizenz:</b> MIT License" \
                    --button="OK:0" 2>/dev/null || true
            else
                yad --info --width=400 --height=420 --image="help-about" --title="ℹ️  About Social-DL" \
                    --text="<span size='x-large'><b>Social-DL</b></span>
<span size='small'>Version 2.7.0</span>

<b>Universal Video &amp; Audio Downloader</b>
for Social Media Platforms

<b>📱 Supported Platforms:</b>
• Instagram
• Twitter / X
• YouTube
• Reddit
• TikTok

<b>💻 Developed with ❤️ by:</b>
• Grok (Base &amp; Features)
• Claude (Security &amp; Production)
• Perplexity (Edge-Cases &amp; Optimizations)

<b>🔗 Repository:</b>
<span foreground='#0969DA'>github.com/socialawkward/social-dl</span>

<b>📄 License:</b> MIT License" \
                    --button="OK:0" 2>/dev/null || true
            fi
            ;;
        "7")  # Ausführen / Run now
            # Finde Terminal
            TERMINAL=""
            for term in x-terminal-emulator konsole gnome-terminal xfce4-terminal xterm; do
                if command -v "$term" >/dev/null 2>&1; then
                    TERMINAL="$term"
                    break
                fi
            done
            
            if [ -n "$TERMINAL" ]; then
                case "$TERMINAL" in
                    konsole)
                        konsole --workdir "$TEMP_DIR" -e bash -c "./social-dl.sh; echo ''; read -p 'Enter zum Schließen... / Press Enter to close...'"
                        ;;
                    gnome-terminal|xfce4-terminal)
                        $TERMINAL --working-directory="$TEMP_DIR" -- bash -c "./social-dl.sh; echo ''; read -p 'Enter zum Schließen... / Press Enter to close...'"
                        ;;
                    *)
                        $TERMINAL -e bash -c "cd '$TEMP_DIR' && ./social-dl.sh; echo ''; read -p 'Enter zum Schließen... / Press Enter to close...'"
                        ;;
                esac
            else
                if [ "$LANG_MODE" = "de" ]; then
                    yad --error --width=360 --image="dialog-error" --title="Fehler" \
                        --text="<b>Kein Terminal gefunden!</b>\n\nBitte führe social-dl.sh manuell aus:\n\n<tt>$TEMP_DIR/social-dl.sh</tt>" \
                        --button="OK:0" 2>/dev/null || true
                else
                    yad --error --width=360 --image="dialog-error" --title="Error" \
                        --text="<b>No terminal found!</b>\n\nPlease run social-dl.sh manually:\n\n<tt>$TEMP_DIR/social-dl.sh</tt>" \
                        --button="OK:0" 2>/dev/null || true
                fi
            fi
            ;;
        "8")  # Settings (handled by show_menu in UI module)
            # This is handled by the UI module's show_menu function
            # If we reach here, something went wrong - just continue
            continue
            ;;
        "9")  # Sprachwechsel / Language switch
            if [ "$LANG_MODE" = "de" ]; then
                LANG_MODE="en"
            else
                LANG_MODE="de"
            fi
            # Check if we should stay in settings
            if [ "${STAY_IN_SETTINGS:-0}" = "1" ]; then
                STAY_IN_SETTINGS=0  # Reset flag
                # Settings will reopen automatically
            fi
            ;;
        
        # === SETTINGS MENU ACTIONS (100-199) ===
        "100")  # Back button (handled by UI module)
            # This is handled by the UI module - should not reach here
            continue
            ;;
        "101")  # Config bearbeiten / Edit config
            CONFIG_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/social-dl/config"
            
            # Create config from example if it doesn't exist
            if [ ! -f "$CONFIG_FILE" ]; then
                mkdir -p "$(dirname "$CONFIG_FILE")"
                cp "$TEMP_DIR/config.example" "$CONFIG_FILE" 2>/dev/null || true
            fi
            
            # Try to find a text editor
            EDITOR_CMD=""
            for editor in gedit kate mousepad pluma xed leafpad nano; do
                if command -v "$editor" >/dev/null 2>&1; then
                    EDITOR_CMD="$editor"
                    break
                fi
            done
            
            if [ -n "$EDITOR_CMD" ]; then
                $EDITOR_CMD "$CONFIG_FILE" &
            else
                if [ "$LANG_MODE" = "de" ]; then
                    yad --info --width=400 --image="dialog-information" --title="Info" \
                        --text="<b>Kein Texteditor gefunden!</b>\n\nÖffne die Datei manuell:\n\n<tt>$CONFIG_FILE</tt>" \
                        --button="OK:0" 2>/dev/null || true
                else
                    yad --info --width=400 --image="dialog-information" --title="Info" \
                        --text="<b>No text editor found!</b>\n\nOpen the file manually:\n\n<tt>$CONFIG_FILE</tt>" \
                        --button="OK:0" 2>/dev/null || true
                fi
            fi
            # Force re-open settings by simulating settings button click
            CHOICE="8"
            ;;
        "102")  # Download Folder / Download-Ordner
            NEW_DIR=$(yad --file --directory --title="Select Download Folder / Download-Ordner wählen" --button="Abbrechen/Cancel:1" --button="Auswählen/Select:0" 2>/dev/null)
            if [ -n "$NEW_DIR" ]; then
                CONFIG_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/social-dl/config"
                mkdir -p "$(dirname "$CONFIG_FILE")"
                
                # Update or create config
                if [ -f "$CONFIG_FILE" ]; then
                    # Update existing
                    if grep -q "^DOWNLOAD_DIR=" "$CONFIG_FILE"; then
                        sed -i "s|^DOWNLOAD_DIR=.*|DOWNLOAD_DIR=\"$NEW_DIR/Videos\"|" "$CONFIG_FILE"
                    else
                        echo "DOWNLOAD_DIR=\"$NEW_DIR/Videos\"" >> "$CONFIG_FILE"
                    fi
                    if grep -q "^AUDIO_DIR=" "$CONFIG_FILE"; then
                        sed -i "s|^AUDIO_DIR=.*|AUDIO_DIR=\"$NEW_DIR/Audio\"|" "$CONFIG_FILE"
                    else
                        echo "AUDIO_DIR=\"$NEW_DIR/Audio\"" >> "$CONFIG_FILE"
                    fi
                else
                    # Create new
                    cat > "$CONFIG_FILE" << 'CONFIG_EOF'
# Social-DL Configuration
DOWNLOAD_DIR="$NEW_DIR/Videos"
AUDIO_DIR="$NEW_DIR/Audio"
CONFIG_EOF
                fi
                
                if [ "$LANG_MODE" = "de" ]; then
                    yad --info --width=320 --image="dialog-information" --title="Erfolg" \
                        --text="<b>Download-Ordner gesetzt!</b>\n\n<tt>$NEW_DIR</tt>" \
                        --button="OK:0" 2>/dev/null || true
                else
                    yad --info --width=320 --image="dialog-information" --title="Success" \
                        --text="<b>Download folder set!</b>\n\n<tt>$NEW_DIR</tt>" \
                        --button="OK:0" 2>/dev/null || true
                fi
            fi
            # Force re-open settings
            CHOICE="8"
            ;;
        "103")  # Retry Count / Wiederholungsversuche
            if [ "$LANG_MODE" = "de" ]; then
                RETRY_COUNT=$(yad --entry --title="Wiederholungsversuche" \
                    --text="Anzahl der Wiederholungsversuche bei Netzwerkfehlern:" \
                    --entry-text="3" \
                    --button="Abbrechen:1" --button="OK:0" 2>/dev/null)
            else
                RETRY_COUNT=$(yad --entry --title="Retry Count" \
                    --text="Number of retry attempts on network errors:" \
                    --entry-text="3" \
                    --button="Cancel:1" --button="OK:0" 2>/dev/null)
            fi
            
            if [ -n "$RETRY_COUNT" ] && [[ "$RETRY_COUNT" =~ ^[0-9]+$ ]]; then
                CONFIG_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/social-dl/config"
                mkdir -p "$(dirname "$CONFIG_FILE")"
                
                if [ -f "$CONFIG_FILE" ]; then
                    if grep -q "^MAX_RETRIES=" "$CONFIG_FILE"; then
                        sed -i "s|^MAX_RETRIES=.*|MAX_RETRIES=$RETRY_COUNT|" "$CONFIG_FILE"
                    else
                        echo "MAX_RETRIES=$RETRY_COUNT" >> "$CONFIG_FILE"
                    fi
                else
                    echo "MAX_RETRIES=$RETRY_COUNT" > "$CONFIG_FILE"
                fi
                
                if [ "$LANG_MODE" = "de" ]; then
                    yad --info --width=320 --image="dialog-information" --title="Erfolg" \
                        --text="<b>Retry-Anzahl gesetzt!</b>\n\n$RETRY_COUNT Versuche" \
                        --button="OK:0" 2>/dev/null || true
                else
                    yad --info --width=320 --image="dialog-information" --title="Success" \
                        --text="<b>Retry count set!</b>\n\n$RETRY_COUNT attempts" \
                        --button="OK:0" 2>/dev/null || true
                fi
            fi
            # Force re-open settings
            CHOICE="8"
            ;;
        "104")  # GitHub Repo
            if command -v xdg-open >/dev/null 2>&1; then
                xdg-open "https://github.com/socialawkward/social-dl" 2>/dev/null &
            elif command -v firefox >/dev/null 2>&1; then
                firefox "https://github.com/socialawkward/social-dl" 2>/dev/null &
            elif command -v chromium >/dev/null 2>&1; then
                chromium "https://github.com/socialawkward/social-dl" 2>/dev/null &
            else
                if [ "$LANG_MODE" = "de" ]; then
                    yad --info --width=400 --image="dialog-information" --title="GitHub Repository" \
                        --text="<b>Repository URL:</b>\n\n<span foreground='#0969DA'>https://github.com/socialawkward/social-dl</span>" \
                        --button="OK:0" 2>/dev/null || true
                else
                    yad --info --width=400 --image="dialog-information" --title="GitHub Repository" \
                        --text="<b>Repository URL:</b>\n\n<span foreground='#0969DA'>https://github.com/socialawkward/social-dl</span>" \
                        --button="OK:0" 2>/dev/null || true
                fi
            fi
            # Force re-open settings
            CHOICE="8"
            ;;
        "105")  # yt-dlp Update
            if [ "$LANG_MODE" = "de" ]; then
                TERM_TITLE="yt-dlp Update"
                UPDATE_CMD="echo '🔧 Aktualisiere yt-dlp...'; echo ''; pip install --upgrade --break-system-packages yt-dlp; echo ''; echo '✅ Fertig!'; echo ''; read -p 'Enter zum Schließen...'"
            else
                TERM_TITLE="yt-dlp Update"
                UPDATE_CMD="echo '🔧 Updating yt-dlp...'; echo ''; pip install --upgrade --break-system-packages yt-dlp; echo ''; echo '✅ Done!'; echo ''; read -p 'Press Enter to close...'"
            fi
            
            # Find terminal
            TERMINAL=""
            for term in x-terminal-emulator konsole gnome-terminal xfce4-terminal xterm; do
                if command -v "$term" >/dev/null 2>&1; then
                    TERMINAL="$term"
                    break
                fi
            done
            
            if [ -n "$TERMINAL" ]; then
                case "$TERMINAL" in
                    konsole)
                        konsole --title "$TERM_TITLE" -e bash -c "$UPDATE_CMD" &
            # Force re-open settings
            CHOICE="8"
            ;;
                    gnome-terminal|xfce4-terminal)
                        $TERMINAL --title="$TERM_TITLE" -- bash -c "$UPDATE_CMD" &
                        ;;
                    *)
                        $TERMINAL -e bash -c "$UPDATE_CMD" &
                        ;;
                esac
            else
                if [ "$LANG_MODE" = "de" ]; then
                    yad --info --width=400 --image="dialog-information" --title="Info" \
                        --text="<b>Kein Terminal gefunden!</b>\n\nFühre manuell aus:\n\n<tt>pip install --upgrade yt-dlp</tt>" \
                        --button="OK:0" 2>/dev/null || true
                else
                    yad --info --width=400 --image="dialog-information" --title="Info" \
                        --text="<b>No terminal found!</b>\n\nRun manually:\n\n<tt>pip install --upgrade yt-dlp</tt>" \
                        --button="OK:0" 2>/dev/null || true
                fi
            fi
            ;;
        
        *)  # Unknown / Exit
            exit 0
            ;;
    esac
done
